{"source": "def investigate(context, acquire):
    actions = context.get('actions', [])
    present = set()
    high = 0
    open_txn = False
    saved = None
    for action in actions:
        op = action.get('op')
        if op == 'put':
            ident = action.get('id')
            present.add(ident)
            if ident > high:
                high = ident
        elif op == 'delete':
            ident = action.get('id')
            if ident in present:
                present.remove(ident)
        elif op == 'begin':
            open_txn = True
            saved = (set(present), high)
        elif op == 'commit':
            open_txn = False
            saved = None
        elif op == 'rollback':
            open_txn = False
            if saved is not None:
                present, high = saved
                saved = None
    return high + 1
